        // proofPurpose of capabilityInvocation and links to the capability
        // chain it is invoking
        "proofPurpose": "capabilityInvocation",
        "capability": {
          "@context": "https://w3id.org/zcap/v1",
          "id": "urn:uuid:d2c83c43-878a-4c01-984f-b2f57932ce5f",
